import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Thibaut Courtois', position: 'GK', age: 33, club: 'Real Madrid', bio: {"es":"¡Mira quién ha vuelto! Bélgica dejó a Courtois en casa para la Eurocopa 2024 debido a una discusión con el entonces entrenador Domenico Tedesco. El italiano-alemán tampoco salió bien librado, siendo despedido poco después. Su sucesor, Rudi García, voló a Madrid para convencer a Courtois de que regresara a sus funciones, y él aceptó, para gran disgusto de Koen Casteels, el hombre que había dado un paso al frente para reemplazarlo. Casteels abandonó rápidamente la selección nacional y dijo: \"Es extraño que le extiendan la alfombra roja y le reciban con los brazos abiertos... A partir de hoy, ya no estoy disponible\". Este verano es otra oportunidad para que Courtois le muestre al mundo exactamente lo bueno que es. Sabe que será difícil ganar el Mundial, pero tal vez pueda sumar otro récord a su colección, que incluye el de más salvadas en una final de la Liga de Campeones (nueve contra el Liverpool en 2022). ¿O podría volver a ganar el Guante de Oro, como lo hizo en 2018? Su esposa, la modelo israelí Mishel Gerzig, seguramente estará en Estados Unidos para apoyarlo, lo cual agradecerá si no está pegado a su teléfono. Una vez lo llamó “el rey de los teléfonos móviles” debido a su fijación, diciendo que regularmente chocaba con los marcos de las puertas mientras lo usaba.","en":"Look who’s back! Courtois was left at home by Belgium for Euro 2024 because of a back-and-forth argument with the then head coach Domenico Tedesco. The German-Italian didn’t come out of it well, either, being fired soon afterwards. His successor, Rudi Garcia, flew to Madrid to convince Courtois to return to duty, and he agreed – much to the distress of Koen Casteels, the man who had stepped up to replace him. Casteels promptly quit the national team, saying: “It's strange that they are rolling out the red carpet and welcoming him back with open arms … As of today, I am no longer available.\" This summer is another chance for Courtois to show the world exactly how good he is. He knows it will be difficult to win the World Cup, but maybe he can add another record to his collection, which includes the record for most saves in a Champions League final (nine against Liverpool in 2022). Or could he win the Golden Glove again, as he did in 2018? His wife, the Israeli model Mishel Gerzig, will surely be in the US to support him, which he’ll appreciate if he isn’t glued to his phone. She once called him “the king of mobile phones” because of his fixation, saying he would regularly bump into door frames while using it."}, special: "Top shot-stopper" },
  { number: 12, name: 'Senne Lammens', position: 'GK', age: 23, club: 'Manchester United', bio: {"es":"“Senne empezó como delantero”, dijo su padre Eddy a Nieuwsblad: “Disparó desde todos los ángulos y marcó con facilidad”. Pero su hijo era aún mejor con el balón en las manos. Se centró en eso, rápidamente dio sus frutos y el verano pasado se convirtió en el portero más caro vendido por un club belga cuando el Manchester United pagó a Amberes 18 millones de libras por él. Rápidamente silenció a los expertos y a los íconos del United que lo descartaron sin conocerlo; sí, tú también, Peter Schmeichel. Este es su primer Mundial, pero no estará nervioso. Al igual que Edwin van der Sar, se le conoce como el \"conejo de hielo\" y lleva un diario de sus pensamientos para mantener la calma. “Antes y después del partido, simplemente escribo las palabras clave y un poco mis pensamientos”, dice. \"Porque, a veces, si no haces eso, pueden pasar muchas cosas por tu mente. Me ayuda a mantener la calma y permanecer en el momento, y no reaccionar exageradamente. Escribo palabras clave, puntos desencadenantes. [Significa] que no tienes que pensar mucho durante los juegos, mentalmente ya estás preparado para el juego y cómo será. No te sorprenderás tanto. Creo que eso es importante\".","en":"“Senne started out as a striker,” his dad Eddy told Nieuwsblad: “He shot from every angle and scored with ease.” But his son was even better with the ball in his hands. He focused on that, it quickly paid off – and last summer he became the most expensive goalkeeper sold by a Belgian club when Manchester United paid Antwerp £18m for him. He quickly silenced the pundits and United icons who wrote him off without knowing him – yes, you too, Peter Schmeichel. This is his first World Cup, but he won’t be nervous. Like Edwin van der Sar, he’s known as the “ice rabbit”, and keeps a journal of his thoughts to stay calm. “Before and after the game, I just write key words down and my thoughts a little bit,” he says. “Because, sometimes, if you don't do that, it can be a lot going through your mind. It helps me stay calm and stay in the moment, and not overreact. I write key words, trigger points. [It means] you don't have to think a lot during the games, mentally you are already prepared for the game and what it's going to be like. You’re not going to be so surprised. I think that is important.”"}, special: "‘The Ice Rabbit’" },
  { number: 13, name: 'Mike Penders', position: 'GK', age: 20, club: 'Chelsea', bio: {"es":"Zurdo, de 2 metros de altura, desarrollado en la academia del Genk y fichado por el Chelsea, no sorprende que a menudo se compare a Penders con Thibaut Courtois. Sin embargo, fue notable que después de sólo un partido de la liga absoluta fuera fichado por el club londinense por £17 millones el año pasado, sobre todo porque ya contaban con seis porteros. Desde entonces, cedido en Estrasburgo, luce el número 39 en la espalda, un homenaje a su abuelo Nico, su mayor admirador. Nico le dijo a Belang van Limburg el año pasado: \"Cuando empezó a jugar cuando era pequeño, yo siempre estaba allí, y más tarde también en Bregel Sport y Genk. Creo que sólo me perdí unas diez sesiones de entrenamiento en los últimos 15 años. Incluso cuando estaba con el primer equipo y las sesiones eran cerradas, me dejaban entrar. Algo que siempre recordaré es que vino a darme un beso en el banquillo antes de un partido. En un estadio lleno, no dejó que nada de eso le molestara. Y lo hizo. ¿Sabes que incluso su número 39 es una referencia a mí? Nací en 1939. Él también jugará con ese número en el Chelsea”.","en":"Left-footed, 2m tall, developed in Genk’s academy and signed by Chelsea – it’s no surprise that Penders is often compared to Thibaut Courtois. It was remarkable, though, that after only one senior league game he was signed by the London club for £17m last year – especially as they already had six goalkeepers. Since then, on loan at Strasbourg, he has worn the No 39 on his back, a tribute to his granddad Nico, his biggest fan. Nico told Belang van Limburg last year: “When he started playing as a little boy I was always there, and later at Bregel Sport and Genk as well. I think I only missed maybe ten of his training sessions in the past 15 years. Even when he was with the first team and the sessions were closed, they would let me in. Something that will always stay with me is that he came to give me a kiss on the sidelines before a match. In a packed stadium, he didn't let any of that bother him. And did you know that even his number 39 is a reference to me? I was born in 1939. He will play with that number at Chelsea as well.”"} },
  // Defensores
  { number: 2, name: 'Zeno Debast', position: 'DF', age: 22, club: 'Sporting', bio: {"es":"Debast, uno de los muchos productos excelentes de la academia de Anderlecht, esperaba convertirse en el próximo Kevin De Bruyne, jugando como mediocampista ofensivo hasta los 15 años. Pero luego, en parte debido a su crecimiento acelerado, fue retrocedido y se destacó en su nuevo rol. Dice que aprendió mucho del actual entrenador de Gales, Craig Bellamy, que entonces era entrenador de la selección sub-21 de Anderlecht: “Antes de trabajar con él, nunca en mi vida había placado a un jugador”, dijo. \"Él también me enseñó a ser más malo\". Ahora, con sus grandes pases de larga distancia y su creciente poder físico, es el líder de la defensa belga. Eso a pesar de enfrentar una gran competencia por lugares a nivel de clubes, y el Sporting a veces lo utiliza como mediocampista de contención. Todos en Bélgica tienen la sensación de que tiene una gran carrera por delante. Es conocido por su apodo, Scampi, que le puso su madre cuando era niño. Cayó en desuso hasta que un compañero de equipo, Benito Raman, lo descubrió en Facebook y con entusiasmo lo volvió a poner en circulación.","en":"One of the many excellent products of Anderlecht’s academy, Debast had been hoping to become the next Kevin De Bruyne, playing as an attacking midfielder until he was 15. But then, partly due to his growth spurt, he was moved back, and excelled in his new role. He says he learned a lot from the current Wales manager Craig Bellamy, who was then coach of Anderlecht’s Under-21s: “Before I worked with him, I had never tackled a player in my life”, he said. “He also taught me to be meaner.” Now, with his great long-range passes and growing physical power, he is the leader of Belgium’s back line. That’s despite facing big competition for places at club level, with Sporting sometimes deploying him as a holding midfielder instead. Everyone in Belgium has the feeling he has a big career ahead of him. He’s known by his nickname, Scampi, which was given to him as a child by his mother. It fell out of use until a teammate, Benito Raman, discovered it on Facebook and eagerly brought it back into circulation."}, special: "Natural leader" },
  { number: 3, name: 'Arthur Theate', position: 'DF', age: 26, club: 'Eintracht Frankfurt', bio: {"es":"Como jugador juvenil, Theate pasó de Genk al Standard Liège, luego regresó a Genk y finalmente a... Standard. Pero no pasó el corte y fue rechazado incluso por clubes de la tercera división antes de que el KV Oostende le diera una oportunidad. A partir de ahí las cosas fueron rápidas para el zaguero zurdo y melenudo, que idolatraba a Carles Puyol. Bolonia, Rennes y Eintracht Frankfurt pagaron millones para ficharlo. Reflexionando sobre sus primeros años difíciles y el empujón que le dieron, le dijo a Humo: \"No siento ningún rencor. Al contrario, doy las gracias a todos los que me rechazaron\". Es un gran aficionado a la F1, por lo que estará atento a las cuatro carreras programadas durante la Copa del Mundo. Y si lo hace bien, incluso podría recibir un mensaje del ciclista doble campeón olímpico y exfutbolista Remco Evenepoel. A nivel juvenil nacional compartieron habitación y todavía están en contacto.","en":"As a youth player, Theate moved from Genk to Standard Liège, then back to Genk and finally to… Standard. But he didn’t make the cut and was rejected even by clubs from the third division before being given a chance by KV Oostende. From there on, things moved quickly for the left-footed and long-haired defender, who idolised Carles Puyol. Bologna, Rennes and Eintracht Frankfurt all paid millions to sign him. Reflecting on his difficult early years, and the push it gave him, he told Humo: “I don’t feel any grudge. On the contrary, I say thanks to all those who rejected me.” He’s a big F1 fan, so will be keeping an eye on the four races scheduled during the World Cup. And if he performs well, he might even receive a message from the double Olympic champion cyclist and former football player Remco Evenepoel. At the national youth level they shared a room, and they’re still in touch."} },
  { number: 4, name: 'Brandon Mechele', position: 'DF', age: 33, club: 'Club Brugge', bio: {"es":"Mechele ya es una leyenda del Club Brugge, con el récord de más apariciones en competiciones europeas (101) y compartiendo el récord de más títulos de liga (seis) con su compañero de equipo Hans Vanaken. Pero no todo ha sido fácil: hubo un momento en el que no se sentía apreciado, y la directiva compraba un nuevo central casi cada año. “Entonces bajé la cabeza y caminé frustrado”, dijo a HLN. \"Es agotador tener que seguir demostrando mi valía ante el mundo exterior\". Sin embargo, nunca pensó en irse. Empezó y quiere terminar su carrera en Brujas, donde va en bicicleta a sus entrenamientos. Estaba realmente decepcionado por haber quedado fuera del equipo belga en torneos anteriores, pero ahora finalmente lo logró. Su íntimo amigo Tibo Debaillie estará contento: juega en Vancouver para el equipo de la Canadian Football League BC Lions, donde los Red Devils se enfrentan a Nueva Zelanda.","en":"Mechele is already a Club Brugge legend, holding the record for most appearances in European competition (101) and sharing the record for most league titles (six) with his teammate Hans Vanaken. But it hasn’t all been plain-sailing: there was a time when he didn’t feel appreciated, with the board buying a new central defender almost every year. “Then I hung my head and walked around in frustration”, he told HLN. “It’s tiring that I have to keep proving myself to the outside world.” Yet he never thought of leaving. He started and wants to finish his career in Bruges, where he rides his bike to training. He was really disappointed to be left out of the Belgium squad for previous tournaments, but now he’s finally made it. His close friend Tibo Debaillie will be happy: he plays for Canadian Football League team BC Lions in Vancouver, where the Red Devils face New Zealand."} },
  { number: 5, name: 'Maxim De Cuyper', position: 'DF', age: 25, club: 'Brighton', bio: {"es":"En septiembre del año pasado, Antoine Semenyo, entonces en Bournemouth, empujó a De Cuyper contra los carteles publicitarios, lesionando la rodilla del lateral del Brighton en su primera temporada en la Premier League. Pasó gran parte del resto de la temporada en el banquillo, pero aún podría ser un jugador importante para Bélgica en este Mundial. Durante años, Bélgica tuvo que desplegar defensores centrales por los lados, como Jan Vertonghen y Thomas Vermaelen, pero con De Cuyper finalmente encontraron un lateral izquierdo natural que también ofrece una amenaza de ataque y gol. El chico de pelo rizado de Knokke es un auténtico producto del Club Brugge, con una fuerte aversión hacia su mayor rival. “En el jardín de infancia, cuando sólo tenía tres años, se negó a colorear el dibujo de una ciruela”, le dijo su madre a Nieuwsblad, porque el morado era el color de Anderlecht. ¿La comida favorita de De Cuyper antes de un partido? Salchicha con puré de manzana y patatas.","en":"In September last year, Antoine Semenyo, then at Bournemouth, knocked De Cuyper into the advertising boards, injuring the Brighton full-back’s knee in his debut season in the Premier League. He spent much of the rest of the season on the bench, but could still be an important player for Belgium at this World Cup. For years Belgium had to deploy central defenders out wide, such as Jan Vertonghen and Thomas Vermaelen, but with De Cuyper they’ve finally found a natural left-back who also offers an attacking and goal-scoring threat. The curly-haired kid from Knokke is a proper Club Brugge product, with a strong aversion to their biggest rival. “In kindergarten, when he was only three years old, he refused to colour a drawing of a plum”, his mother told Nieuwsblad – because purple was Anderlecht’s colour. De Cuyper’s favourite meal before a game? Sausage with apple sauce and potatoes."} },
  { number: 15, name: 'Thomas Meunier', position: 'DF', age: 34, club: 'Lille', bio: {"es":"La leyenda de la NBA Karl Malone era llamada \"El cartero\" porque siempre entregaba, pero Meunier literalmente trabajaba como cartero antes de convertirse en profesional. Pronto se produjo otro gran cambio en su carrera mientras se instalaba en el Club Brugge: comenzó como extremo izquierdo, luego avanzó por todo el campo hasta convertirse en lateral derecho, y uno muy bueno, además. Su habilidad natural en la posición le valió un gran traslado al Paris Saint-Germain en 2016, donde ganó una serie de honores, y luego a Dortmund en 2020. Ahora, con 34 años, dijo recientemente que espera seguir jugando hasta los 40. Pero si el final llega antes, no se aburrirá fuera del juego. Además de tener tres hijos, también tiene sus negocios en Bastogne, donde creció, incluido un restaurante de pollo asado, y su amor por el arte. Le gusta visitar museos e incluso tenía una fotografía de La persistencia de la memoria de Salvador Dalí como salvapantallas de su teléfono.","en":"The NBA legend Karl Malone was called “The Mailman” because he always delivered, but Meunier was literally working as a postman before he turned pro. Another big career switch soon followed while he settled in at Club Brugge: he began as a left winger, then moved all the way across the field to become a right-back – and a very good one, too. His natural ability in the position earned him a big move to Paris Saint-Germain in 2016 where he won a string of honours, and then to Dortmund in 2020. Now 34, he said recently he hopes to keep playing until he is 40. But if the end comes sooner than that, he won’t be bored away from the game. Besides having three kids, he also has his businesses in Bastogne, where he grew up, including a rotisserie chicken restaurant, and his love for art. He likes to visit museums and even used to have a picture of Salvador Dalí’s The Persistence of Memory as his phone screensaver."}, special: "Former postman" },
  { number: 16, name: 'Koni De Winter', position: 'DF', age: 23, club: 'Milan', bio: {"es":"Los aficionados belgas oyeron por primera vez el nombre de De Winter hace ocho años, cuando, sin siquiera haber debutado con la absoluta en Zulte Waregem, el joven de 16 años fue fichado por la Juventus. Se convirtió en el titular más joven de la Juve en la Liga de Campeones y disfrutó de la oportunidad de entrenar con Cristiano Ronaldo y aprender de Leonardo Bonucci y Giorgio Chiellini. Pero al final necesitó cesiones en Empoli y Génova para ganar experiencia antes de que la Juve lo vendiera a Génova, una decisión de la que quizás ya se arrepientan en Turín. El verano pasado, el Milán pagó más de 17 millones de libras para ficharlo y desde entonces se ha convertido en un jugador clave allí. Ahora sabemos por qué sus entrenadores juveniles solían compararlo con uno de los grandes de todos los tiempos. \"Se parecía un poco al joven Vincent Kompany\", dijo Bert Wets a HLN. \"Tenía mucha elegancia, estilo y trucos sofisticados\". Esas cualidades solían significar algunos errores costosos, pero son cada vez más raros. Su primer nombre, Koni, no fue la primera elección de su padre. \"Cuando era niño veía los partidos de la Liga de Campeones del Milán en la televisión y jugaba a los rossoneri en mi PlayStation. Mi padre los veía incluso antes de que yo naciera. Le gustaba Seedorf y quería ponerme su nombre, Clarence\".","en":"Belgian fans first heard the name De Winter eight years ago when, without even having made his senior debut at Zulte Waregem, the 16-year-old was signed by Juventus. He became Juve’s youngest starter ever in the Champions League and relished the chance to train with Cristiano Ronaldo and learn from Leonardo Bonucci and Giorgio Chiellini. But in the end he needed loan spells at Empoli and Genoa to gain experience before Juve sold him to Genoa – a decision they may already regret in Turin. Last summer Milan paid over £17m to sign him, and he has since become a key player there. Now we know why his youth coaches used to compare him to an all-time great. “He was a bit like the young Vincent Kompany,” Bert Wets told HLN. “He had lots of elegance, flair and fancy tricks.” Those qualities used to mean some costly mistakes, but they are becoming rarer. His first name, Koni, wasn’t his dad’s first choice. “As a child I watched Milan’s Champions League matches on TV and played the Rossoneri on my PlayStation. My dad watched them even before I was born. He liked Seedorf and wanted to name me after him, Clarence.”"} },
  { number: 18, name: 'Joaquin Seys', position: 'DF', age: 21, club: 'Club Brugge', bio: {"es":"El sucesor de Maxim De Cuyper en el Club Brujas, sólo que con rizos rubios en lugar de castaños. Cuando era niño, a Seys le gustaba patinar, a pesar de todos los cortes y magulladuras, pero decidió dedicarse a convertirse en futbolista. Alrededor de los 15 años le faltaban fuerzas, pero los entrenadores lo apoyaron, reconociendo que era un jugador tardío, y se hizo más fuerte año tras año, hasta que finalmente consiguió su primer contrato profesional. Y aunque es zurdo, pronto se consagró como un excelente lateral derecho. Se podría suponer que lleva el nombre del famoso actor Joaquin Phoenix, pero en realidad proviene de Joaquín Cortés, un bailarín de flamenco español. Así lo explicó su padre, con quien comparte un estrecho vínculo. Ambos tienen tatuadas en el cuerpo las palabras “sempre con voi”, que en italiano significa “siempre contigo”.","en":"Maxim De Cuyper’s successor at Club Brugge, just with blonde curls instead of brown. As a young boy Seys enjoyed skating, despite all the cuts and bruises, but he chose to dedicate himself to becoming a footballer instead. Around the age of 15 he lacked strength, but coaches stuck by him, recognising he was a late bloomer – and he grew stronger year by year, eventually earning his first professional deal. And although he’s left-footed, he soon established himself as a fine right-back. You might assume he’s named after the famous actor Joaquin Phoenix, but in fact it comes from Joaquín Cortés, a Spanish flamenco dancer. That was explained by his father, with whom he shares a close bond. They both have the words “sempre con voi” tattooed on their bodies, which is Italian for “always with you”."} },
  { number: 21, name: 'Timothy Castagne', position: 'DF', age: 31, club: 'Fulham', bio: {"es":"La vida nunca ha sido fácil para Castagne. Cuando era niño sufría de exoforia y sus ojos se desviaban ligeramente hacia afuera. Esa condición se corrigió sola, pero, después de sufrir una lesión en la cabeza en un partido con Genk en 2015, quedó con visión doble severa y migrañas, y necesitó una cirugía ocular, lo que lo dejó fuera durante meses. Luego vino su primer gran torneo con la selección nacional, la Eurocopa 2020, y otra colisión grave, en una victoria en la fase de grupos sobre Rusia, que le fracturó la cuenca del ojo y le obligó a tener que someterse a más operaciones. “En el avión de regreso a casa lo único que podía hacer era llorar”, dijo a Nieuwsblad, pero todavía se considera afortunado. Si el impacto hubiera sido ligeramente mayor, podría haber acabado con su carrera. Pero cinco años después de ese trauma, el versátil lateral derecho, que también puede trabajar en la izquierda, es un jugador consolidado de la Premier League. También es un verdadero hombre de familia. Lleva muchos años con Camille, la hija de su agente Zénon Melon; su segunda hija nació el día de San Valentín.","en":"Life has never been easy for Castagne. As a child he suffered from exophoria, with his eyes drifting slightly outwards. That condition corrected itself, but, after sustaining a head injury in a match for Genk in 2015 he was left with severe double vision and migraines, and needed eye surgery, sidelining him for months. Then came his first major tournament with the national side – Euro 2020 – and another serious collision, in a group-stage win over Russia, which fractured his eye socket and meant more surgery. “On the plane home, all I could do was cry”, he told Nieuwsblad – but he still considers himself lucky. Had the impact been slightly higher it could have ended his career. But five years on from that trauma the versatile right-back, who can also do a job on the left, is an established Premier League player. He’s also a real family man. He’s been with Camille, the daughter of his agent Zénon Melon, for many years; their second daughter was born on Valentine’s Day."} },
  { number: 25, name: 'Nathan Ngoy', position: 'DF', age: 22, club: 'Lille', bio: {"es":"Ngoy comenzó como delantero en la academia juvenil de Anderlecht, donde marcar goles era algo natural. Y ese instinto sigue ahí. A finales de febrero disfrutó de una semana de ensueño. En la Europa League, el belga de raíces congoleñas salió del banquillo en la prórroga contra el Estrella Roja de Belgrado y anotó el gol de la victoria que dio la clasificación al Lille. Apenas unos días después, volvió a marcar, anotando el gol decisivo en el minuto 94 contra el Nantes tras una asistencia de Thomas Meunier. Su conversión a defensor ocurrió en la academia cuando los entrenadores se dieron cuenta de que su ritmo y técnica funcionarían bien en la zaga. A los 16 años se fue a su rival Standard y hizo su debut profesional en 2021, anotando su primer gol como profesional en la remontada por 3-2 contra... Anderlecht. Ahora en el Lille, al que llegó el año pasado, se ha convertido rápidamente en un jugador clave. También puede jugar como lateral cuando sea necesario.","en":"Ngoy started out as a striker in Anderlecht’s youth academy, where scoring goals came naturally. And that instinct is still there. At the end of February, he enjoyed a dream week. In the Europa League, the Belgian with Congolese roots came off the bench in extra time against Red Star Belgrade and scored the winner to send Lille through. Just days later, he struck again, netting a 94th-minute decider against Nantes after an assist from Thomas Meunier. His conversion into a defender happened at the academy when coaches realised his pace and technique would work well at the back. At 16 he left for rivals Standard, and went on to make his professional debut in 2021, scoring his first goal as a professional in a 3-2 comeback win against … Anderlecht. Now at Lille, whom he joined last year, he has quickly become a key player. He can also play at full-back when needed."} },
  // Volantes
  { number: 6, name: 'Axel Witsel', position: 'MF', age: 36, club: 'Girona', bio: {"es":"El Diablo Rojo más viejo. Witsel hizo su debut internacional en 2008, cuando su compañero Nathan De Cat ni siquiera había nacido. Witsel tiene ahora 37 años pero sigue firme gracias a su ética de trabajo que, según su padre Thierry, con quien dirige una academia de fútbol, ​​es \"similar a la de Cristiano Ronaldo\". En los últimos años, Witsel también comenzó a evitar los carbohidratos por la noche y usa una pulsera WHOOP para realizar un seguimiento de su carrera, su sueño y su salud en general. No jugó con Bélgica durante casi tres años para centrarse en su carrera en el club, pero admitió que lamentaba esa decisión. Se espera que desempeñe un papel clave este verano, pero más fuera del campo que dentro. Sin embargo, si tiene más minutos de los previstos, podremos admirar sus famosos tatuajes una vez más. Además del padrenuestro en su pecho, sus brazos ahora están completamente entintados, incluidos los nombres de sus hijos y una imagen de un león rugiente.","en":"The oldest Red Devil. Witsel made his international debut in 2008 when teammate Nathan De Cat hadn’t even been born. Witsel is now 37 but still standing strong thanks to his work ethic, which, said his father Thierry, with whom he runs a football academy, is “similar to that of Cristiano Ronaldo”. In recent years Witsel also started skipping carbs in the evening and he wears a WHOOP bracelet to track his running, sleep and overall health. He didn’t play for Belgium for almost three years, to focus on his club career, but he admitted that he regretted that decision. He is expected to play a key role this summer, but more off the pitch than on it. If he does get more minutes than anticipated, though, we’ll be able to admire his famous tattoos once more. Apart from the paternoster on his chest, his arms are now fully inked, including the names of his kids, and an image of a roaring lion."}, special: "Veteran" },
  { number: 7, name: 'Kevin De Bruyne', position: 'MF', age: 34, club: 'Napoli', captain: true, bio: {"es":"¿Qué tienen en común Jamal Musiala, Gavi y Anthony Gordon? Todos jugaron en la Copa KDB, el prestigioso torneo juvenil que lleva 10 años y que lleva el nombre (y apoyado por) Kevin De Bruyne. Sus propios años de juventud, cuando frecuentemente se escapaba de los entrenamientos debido a discusiones con los entrenadores, apoyaba al Liverpool y fue a prueba en el Arsenal, parecen haber quedado atrás. Llega al Mundial como un estadista veterano, una leyenda del Manchester City, con 422 partidos, 108 goles y 19 trofeos, y uno de los últimos miembros de la “generación dorada” de Bélgica. Sin duda espera tener un mejor desempeño que en el Mundial anterior. De lo contrario, volará a casa el día de su cumpleaños número 35, ya que es justo después del partido contra Nueva Zelanda. Pero pase lo que pase, el futuro de la familia parece brillante después de que surgieran imágenes de su hijo Rome, de siete años, marcando algunos de los goles característicos de su padre en el Real Casarea, un club del área de Napoli.","en":"What do Jamal Musiala, Gavi and Anthony Gordon have in common? They all played in the KDB Cup, the now 10-year-old prestigious youth tournament named after (and supported by) Kevin De Bruyne. His own younger years – back when he frequently ran away from training because of arguments with coaches, was supporting Liverpool and went on a trial at Arsenal – seem a long time ago now. He arrives at the World Cup as an elder statesman, a Manchester City legend, with 422 games, 108 goals and 19 trophies, and one of Belgium’s last “golden generation” members. He certainly hopes to perform better than at the previous World Cup. If not, he’ll be flying home on his 35th birthday, since it falls right after the New Zealand game. But whatever happens, the family’s future looks bright after footage emerged of his seven-year-old son Rome scoring some of his dad’s trademark goals at Real Casarea, a club in the Napoli area."}, special: "Global star" },
  { number: 8, name: 'Youri Tielemans', position: 'MF', age: 28, club: 'Aston Villa', bio: {"es":"Este año Tielemans celebra su décimo aniversario como Diablo Rojo. Los aficionados belgas todavía lo recuerdan cuando tenía 18 años en la ceremonia de iniciación de su equipo cantando Cheerleader de Omi frente a sus compañeros. Y ahora, en su quinto gran torneo, quiere desempeñar por primera vez un papel clave. Y debería hacerlo, porque Rudi García lo ha nombrado capitán, lo cual es todo un honor teniendo en cuenta que Thibaut Courtois, Kevin De Bruyne y Romelu Lukaku también están en la plantilla. Sin embargo, Tielemans fue la elección menos controvertida: no sólo habla holandés y francés con fluidez, sino que es querido por casi todo el mundo. Además de sus grandes pies (con ambos marca goles, como su inolvidable gol de la victoria para Leicester en la final de la Copa FA de 2022 contra el Chelsea), siempre pone al equipo en primer lugar. Negative stories? No encontrarás ninguno. Tampoco habla nunca de su vida privada, por lo que tomó un tiempo comprobar que ahora tiene tres hijas en lugar de dos.","en":"This year Tielemans celebrates his 10th anniversary as a Red Devil. Belgium fans still remember him as an 18-year old at his squad initiation ceremony singing Cheerleader by Omi in front of his teammates. And now, in his fifth major tournament, he wants to play a key role for the first time. And he should, because Rudi Garcia has named him captain, which is quite some honour with Thibaut Courtois, Kevin De Bruyne and Romelu Lukaku also in the squad. Tielemans was the least controversial choice, though: not only does he speak Dutch and French fluidly, he is loved by nearly everyone. Besides his great feet – he scores screamers with both, such as his unforgettable winner for Leicester in the FA Cup final in 2022 against Chelsea – he always puts the team first. Negative stories? You won’t find any. He also never talks about his private life, so it took a while to double check that he now has three daughters rather than two."}, special: "Creative force" },
  { number: 20, name: 'Hans Vanaken', position: 'MF', age: 33, club: 'Club Brugge', bio: {"es":"A Vanaken le gusta coleccionar cosas. El creador de juego ya tiene seis títulos belgas (con el Club Brugge) y tres Botas de Oro al mejor jugador de la liga belga, pero su colección de camisetas de fútbol es igualmente impresionante. Tiene alrededor de 350, muchos de ellos obtenidos intercambiando con oponentes. Sin embargo, falta uno: la camiseta internacional de Lionel Messi. Ya tiene una de las CABRA de cuando jugó contra el Paris St-Germain. \"Tengo que agradecer a nuestro presidente, Bart Verhaeghe, que entró en su vestuario\", dijo a Sporza. Pero la camiseta argentina celeste y blanca de Messi está en lo más alto de su lista de deseos. ¿Podrían enfrentarse en este Mundial? Una cosa que no le gusta coleccionar son las tarjetas amarillas y rojas, pero le encanta jugar a las cartas con sus compañeros mientras viaja para partidos fuera de casa. Sabrá qué hacer durante los largos vuelos de las próximas semanas.","en":"Vanaken likes to collect things. The playmaker already has six Belgian titles (with Club Brugge) and three Golden Boots for best player in the Belgian league, but his collection of football shirts is equally impressive. He has around 350, many of them obtained by swapping with opponents. One is missing though: Lionel Messi’s international shirt. He’s already got one of the GOAT from when he played against Paris St-Germain. “I have to thank our president, Bart Verhaeghe, who went into their dressing room,” he told Sporza. But Messi’s light blue and white Argentina jersey is at the top of his wishlist. Could they meet at this World Cup? One thing he doesn’t like to collect is yellow and red cards, but he does love playing cards with his teammates while travelling for away games. He’ll know what to do during the long flights in the weeks ahead."}, special: "Football shirt collector" },
  { number: 23, name: 'Nicolas Raskin', position: 'MF', age: 25, club: 'Rangers', bio: {"es":"Cuando Rudi García se convirtió en el entrenador de Bélgica, sacó un conejo (o deberíamos decir un Raskin) de la chistera. El jugador del Rangers, que entonces tenía 24 años, nunca había sido convocado, pero de la nada se convirtió inmediatamente en un pilar del mediocampo, tal como su ex entrenador Hein Vanhaezebrouck había predicho en su columna para Nieuwsblad seis años antes: “Un día”, escribió Vanhaezebrouck, “será titular indiscutible en la selección nacional”. A pesar de ser unos 15 cm más bajo que Amadou Onana, Raskin ha marcado cinco goles de cabeza en las últimas dos temporadas y compensa su falta de altura con toneladas de energía y pies rápidos. Siempre ha sido un pequeño pitbull, apodado \"el Raskinator\" en el Standard, pero fue Philippe Clement quien le ayudó a mejorar tácticamente: \"Nico era bombero. A menudo iba a apagar incendios en otros lugares, lo que causaba problemas en su propia zona\", dijo a HLN. “Ahora ya no hace eso”.","en":"When Rudi Garcia became Belgium’s head coach, he pulled a rabbit – or should we say a Raskin – out of the hat. The then 24-year-old Rangers player had never been called up, but out of nowhere he immediately became a mainstay in the midfield – just as his former manager Hein Vanhaezebrouck had predicted in his column for Nieuwsblad six years earlier: “One day,” Vanhaezebrouck wrote, “he’ll be an undisputed starter for the national team”. Despite being about 15cm shorter than Amadou Onana, Raskin has still scored five headers in the last two seasons and compensates for his lack of height with tons of energy and quick feet. He’s always been a little pitbull, nicknamed “the Raskinator” at Standard, but it was Philippe Clement who helped him improve tactically: “Nico was a fireman. He often went to put out fires elsewhere, which caused problems in his own zone,” he told HLN. “Now he no longer does that.”"} },
  { number: 24, name: 'Amadou Onana', position: 'MF', age: 24, club: 'Aston Villa', bio: {"es":"Onana podría haber ganado la final de la Copa Africana de Naciones este año, ya que nació en Senegal y se mudó a Bruselas cuando tenía 11 años. Pero siempre ha jugado en Bélgica, donde se le conoce como un jugador con estilo, incluso fuera del campo. Una vez se presentó a cumplir funciones internacionales vistiendo una falda de hombre. \"La moda es un ámbito donde encuentro expresión y creatividad\", dice. \"Disfruto experimentando con diferentes looks e incluso he incursionado en el diseño de mis propias piezas. La moda, al igual que el fútbol, ​​es para mí una forma de conectar con la gente y compartir una parte de mí con el mundo\". En el campo, es el Marouane Fellaini de su generación, no sólo porque jugó en el Everton, sino también porque es una auténtica potencia. Y lo mejor está por llegar. “Un día jugaré en uno de los cinco clubes más grandes del mundo”, dijo a La Dernière Heure. ¿Quién lo hubiera pensado? No la gente de Anderlecht o Zulte Waregem, donde se pasó por alto su talento. Fue gracias a su hermana y agente Melissa que se hizo notar. Compró una cámara de vídeo para filmar a su hermano en el entrenamiento y envió las imágenes a numerosos clubes europeos.","en":"Onana could have won the African Cup of Nations final this year, since he was born in Senegal and only moved to Brussels at the age of 11. But he has always played for Belgium, where he is known as a stylish player, including off the pitch. He once reported for international duty wearing a men’s skirt. “Fashion is a realm where I find expression and creativity,” he says. “I enjoy experimenting with different looks and have even dabbled in designing my own pieces. Fashion, much like football, is a way for me to connect with people and share a part of myself with the world.” On the pitch, he is the Marouane Fellaini of his generation, not only because he played for Everton, but also because he’s a real powerhouse. And the best is yet to come. “One day, I’ll play for one of the five biggest clubs in the world”, he told La Dernière Heure. Who would have thought? Not the people at Anderlecht or Zulte Waregem, where his talent was overlooked. It was thanks to his sister and agent Melissa that he got noticed. She bought a video camera to film her brother at training, and sent the footage to numerous European clubs."}, special: "Midfield powerhouse" },
  // Delanteros
  { number: 9, name: 'Romelu Lukaku', position: 'FW', age: 33, club: 'Napoli', bio: {"es":"Algunos delanteros no marcan 89 goles en toda su carrera. Lukaku llegó a este Mundial con 89 goles sólo para su país. Eso es más del doble que cualquier otro jugador belga, y por eso su apodo \"Big Rom\" no es solo una referencia a su corpulento cuerpo de 1,91 m. En este torneo tendrá una misión. Hace cuatro años, en Qatar, no estaba del todo en forma y desperdició grandes oportunidades como suplente contra Croacia. “Después, de vacaciones, durante una semana seguida estuve llorando todos los días”, le dijo a Koolcast más tarde. Además de sus hijos Jordan y Romeo, fue el legendario Thierry Henry, ex asistente de la selección nacional, quien le brindó el apoyo mental que necesitaba. La temporada pasada, Lukaku tuvo mala suerte con su lesión en el tendón de la corva, lo que provocó una pelea con el cuerpo técnico y la directiva del Napoli, ya que el delantero optó por completar gran parte de su rehabilitación en Amberes. Pero incluso sin muchos minutos a su nombre en 2025-26, los defensores seguirán temiendo su fuerza y ​​eficiencia.","en":"Some strikers don’t score 89 goals in their entire career. Lukaku arrived at this World Cup having scored 89 for his country alone. That’s over twice as many as any other Belgian player – and why his nickname “Big Rom” isn’t just a reference to his bulky 1.91m frame. At this tournament he will be on a mission. Four years ago, in Qatar, he wasn’t fully fit and missed some big chances as a substitute against Croatia. “Afterwards, on vacation, for a week straight I was crying every day”, he told Koolcast later on. Apart from his sons Jordan and Romeo, it was the legendary Thierry Henry, former assistant of the national team, who gave him the mental support he needed. Last season Lukaku had his share of bad luck with his hamstring injury, which led to a falling out with the coaching staff and board at Napoli as the striker opted to complete a big part of his rehab in Antwerp. But even without many minutes to his name in 2025-26, defenders will still fear his strength and efficiency."}, special: "Goal machine" },
  { number: 10, name: 'Leandro Trossard', position: 'FW', age: 32, club: 'Arsenal', bio: {"es":"Hace diez años, Trossard descendía a la segunda división belga con el OH Leuven. Una década después, es un jugador de la Copa del Mundo que acaba de pasar una temporada en el centro de la lucha por el título de la Premier League. Sin embargo, no es inmune a las críticas, ya que los medios y los aficionados belgas suelen decir que no se desempeña al mismo nivel para su país que para su club. En una conferencia de prensa en octubre, por ejemplo, un periodista incluso le dijo que siempre parece menos feliz cuando está con la selección nacional. Trossard sonrió, mostró sus dientes blancos y respondió: \"No tengo idea de dónde viene eso. Siempre estoy feliz cuando estoy en el campo\". Espera demostrarlo en el Mundial y, si encuentra la red, cuidado con que se ponga sus gafas imaginarias, su celebración característica. También esté atento a los partidos de Bélgica arbitrados por el árbitro francés Clément Turpin, que es el doble de Trossard.","en":"Ten years ago Trossard was being relegated to Belgium’s second division with OH Leuven. A decade on, he’s a World Cup player who has just spent a season at the heart of a Premier League title challenge. He’s not immune to criticism, though, with Belgium media and fans often saying he doesn’t perform at the same level for his country as he does for his club. In a press conference in October, for instance, a reporter even told him that he always looks less happy when he’s with the national team. Trossard smiled, flashed his white teeth and countered: “No idea where that comes from. I’m always happy when I’m on the field.” He hopes to show that at the World Cup and, if he finds the net, watch out for him putting on his imaginary glasses – his signature celebration. Also watch out for any Belgium matches refereed by the French official Clément Turpin, who is Trossard’s doppelganger."} },
  { number: 11, name: 'Jérémy Doku', position: 'FW', age: 24, club: 'Manchester City', bio: {"es":"¿Cuántas veces veremos a Doku tocar el “Griddy” (su celebración de baile característica) en la Copa del Mundo? Los aficionados belgas no lo vieron con suficiente frecuencia la temporada pasada, pero con cinco goles y tres asistencias, el veloz y prolífico regateador siguió siendo uno de los jugadores más importantes de las eliminatorias. Si se mantiene en forma y se desempeña bien, los fanáticos seguramente disfrutarán de otro episodio de su “dokumentario” en YouTube; Los episodios anteriores incluyeron hablar sobre su fe y llevar a los espectadores a Ghana, donde nacieron sus padres. Sin embargo, su padre ya era muy conocido gracias a una historia que contó sobre el momento en que su hijo, entonces en el sistema juvenil de Anderlecht, estaba siendo mostrado por el complejo de entrenamiento del Liverpool antes de una posible transferencia. Su padre le dijo a Nieuwsblad que, cuando les mostraban el lugar, el personal del Liverpool parecía nervioso porque \"hablábamos del Chelsea con bastante frecuencia. El Liverpool tenía miedo de que Jérémy firmara allí. Pero solo estábamos hablando de nuestra hija menor. Su nombre es Chelsea\".","en":"How many times will we see Doku hit the “Griddy” (his trademark dance celebration) at the World Cup? Belgium fans didn’t see it often enough last season, but with five goals and three assists the speedster and prolific dribbler was still one of the most important players in the qualifiers. If he stays fit and performs well fans will surely be treated to another episode of his “dokumentary” on YouTube; previous episodes have included discussing his faith, and taking viewers to Ghana, where his parents were born. His dad was already well-known, though, thanks to a story he told about the time his boy, then in the youth system at Anderlecht, was being shown around Liverpool’s training complex ahead of a possible transfer. His dad told Nieuwsblad that, when they were being shown around, the Liverpool staff seemed twitchy because “we were talking about Chelsea quite often. Liverpool were afraid that Jérémy would sign there instead. But we were just talking about our youngest daughter. Her name is Chelsea.”"}, special: "Speed bullet" },
  { number: 14, name: 'Dodi Lukébakio', position: 'FW', age: 28, club: 'Benfica', bio: {"es":"\"Estoy muy agradecido. Después de mi primer gol, incluso lloré\", dijo tras su sublime actuación contra Estados Unidos a finales de marzo. \"Esto significa mucho para mí\". La emotiva respuesta se explica porque el extremo sufrió una fractura de tobillo, que arruinó la mitad de su temporada de debut en el Benfica, y le hizo temer que eso arruinaría sus posibilidades de jugar su primer gran torneo. Pero todo salió bien y ahora ha llegado al escenario más grande. Ahora el mundo sabrá quién es Dodi, aunque aún existen dudas sobre el origen de su nombre. Según su madre, se refiere a Dodi Fayed, que murió en un accidente en París junto a la princesa Diana menos de un mes antes del nacimiento de Lukebakio. Pero según su padre, Dodi significa Don de Dieu, que en francés significa \"regalo de Dios\". La última explicación le agrada más, ya que él mismo es muy religioso.","en":"“I’m so grateful. After my first goal I was even in tears,” he said after his sublime performance against the US at the end of March. “This means so much to me.” The emotional response was explained by the winger having suffered an ankle fracture, which ruined half of his debut season at Benfica, and left him fearing it would ruin his chances of playing at his first major tournament. But it all worked out and he has now made it to the biggest stage. Now the world will know who Dodi is, although there are still doubts about the origin of his name. According to his mother, it refers to Dodi Fayed, who died in an accident in Paris alongside Princess Diana less than a month before Lukebakio's birth. But according to his father, Dodi stands for Don de Dieu, which is French for ‘gift from God’. The last explanation pleases him most, since he’s very religious himself."} },
  { number: 17, name: 'Charles De Ketelaere', position: 'FW', age: 24, club: 'Atalanta', bio: {"es":"De Ketelaere, campeón de tenis flamenco a los diez años, podría haber seguido el camino de su ídolo Roger Federer. Por suerte para los aficionados belgas, tomó una decisión diferente. Al explicar cómo tomó la decisión cuando era joven, le dijo a Nieuwsblad: “Siempre recibir lecciones privadas de un entrenador adulto o jugar con tus amigos: ¿qué crees que le gusta más a un niño de esa edad?” Su personalidad en el tenis tenía que ver con la agresión, siendo amonestado por decir malas palabras y destrozar sus raquetas. En el fútbol, ​​no podría ser más diferente, a menudo considerado como el material perfecto para el yerno. Quizás su carácter relajado fue una de las razones por las que, a pesar de su talento y tres títulos con el Club Brugge, no triunfó en Milán, donde la competencia y la presión son enormes. En 40 partidos no marcó un solo gol. En Atalanta, sin embargo, el polivalente delantero juega un papel muy importante y ya tiene una medalla de ganador de la Europa League a su nombre.","en":"A Flemish tennis champion at the age of ten, De Ketelaere could have followed the path of his idol Roger Federer. Luckily for Belgium fans, he made a different choice. Explaining how he made the decision as a youngster, he told Nieuwsblad: “Always getting private lessons from an adult coach or playing with your friends: what do you think a boy of that age likes best?” His personality in tennis was all about aggression, being admonished for swearing and smashing his rackets. In football, he couldn’t be more different, often regarded as perfect son-in-law material. Maybe his laid-back nature was one of the reasons why, despite his talent and three titles with Club Brugge, he didn’t succeed at Milan, where the competition and pressure are huge. In 40 games he didn’t score a single goal. At Atalanta, however, the versatile forward plays a very important role, and has a Europa League winner’s medal to his name already."} },
  { number: 19, name: 'Diego Moreira', position: 'FW', age: 22, club: 'Strasbourg', bio: {"es":"Moreira proviene de pura cepa futbolística. Su padre, Almani Moreira, fue uno de los favoritos de los aficionados en el Standard de 2001 a 2006, y su abuelo materno, Helmut Graf, también jugó para ellos de 1976 a 1982. Nacido en Lieja, pasó por las categorías inferiores del Standard, pero se marchó a los 16 años al Benfica, donde destacó durante la campaña ganadora de la Uefa Youth League. Más tarde hizo su debut absoluto, pero rechazó un nuevo contrato y se fue, pasando por Chelsea y Lyon antes de encontrar estabilidad en Estrasburgo en la Ligue 1. A nivel internacional, representó a Portugal desde la categoría juvenil hasta la sub-21, antes de pasar a Bélgica en la categoría absoluta. Se le considera un jugador moderno y versátil que puede jugar como extremo o volver a ser lateral en ambos lados.","en":"Moreira comes from pure football stock. His father Almani Moreira was a fan favourite at Standard from 2001 to 2006, and his grandfather on his mother’s side, Helmut Graf, also played for them from 1976 to 1982. Born in Liège, he came through the youth ranks at Standard but left at 16 for Benfica, where he was outstanding during their Uefa Youth League winning campaign. He later made his senior debut, but refused a new contract and left, passing through Chelsea and Lyon before finding stability at Strasbourg in Ligue 1. Internationally, he represented Portugal at youth level up to the under-21s, before switching to Belgium at senior level. He’s seen as a modern, versatile performer who can play as a winger or drop back to full-back on both sides."} },
  { number: 22, name: 'Alexis Saelemaekers', position: 'FW', age: 26, club: 'Milan', bio: {"es":"Saelemaekers ganó su primer partido internacional en 2020, pero desde entonces fue ignorado en todos los torneos importantes, una vez debido a una lesión. Sin embargo, convenció plenamente a Rudi García de su valía y sólo se perdió un partido durante la clasificación para el Mundial. No fue una sorpresa porque acaba de hacer su mejor temporada en Milán. Extremo derecho, que también puede jugar como lateral o lateral, estuvo prácticamente siempre presente en el equipo de Milán y firmó un nuevo contrato por cinco años, un gran cambio después de haber sido cedido al Bolonia y la Roma en las dos temporadas anteriores. El portero Asmir Begovic, que estuvo cedido en Milán en 2020 cuando ficharon por primera vez a Saelemaekers, habló recientemente sobre la confianza en sí mismo del delantero y le contó a Talksport cómo se adelantó un poco durante sus primeros días en Italia. \"Los primeros días después de su llegada estuvo tranquilo, pero dos semanas después vino al club en su nuevo Porsche. Lo primero que hizo Zlatan Ibrahimović fue tomar sus llaves. Le dijo: 'Escucha, vas a llevar este auto al garaje. Si no, lo haré yo mismo'\".","en":"Saelemaekers won his first cap in 2020, but was ignored for all major tournaments since then, once because of injury. However, he has fully convinced Rudi Garcia of his worth, and only missed one game during the World Cup qualifiers. That was no surprise because he has just had his best season ever at Milan. A right-winger, who can also play as a full-back or wing-back, he was virtually an ever-present in Milan’s side, and signed a new five-year deal – quite a turnaround after he was loaned to Bologna and Roma in the two previous seasons. Goalkeeper Asmir Begovic, who was on loan at Milan in 2020 when they first signed Saelemaekers, recently talked about the forward’s self-confidence, telling Talksport how he may have got ahead of himself a bit during his early days in Italy. “The first few days after he arrived he was quiet, but two weeks later he came to the club in his new Porsche. The first thing Zlatan Ibrahimović did was to take his keys. He told him: ‘Listen, you’re taking this car back to the garage. If not, I’ll do it myself.’”"} },
  { number: 26, name: 'Matias Fernandez-Pardo', position: 'FW', age: 21, club: 'Lille', bio: {"es":"\"Mi corazón está con España. ¿Estoy seguro de para quién quiero jugar? Sí, España. Absolutamente seguro\". Esas fueron las palabras de Fernández-Pardo en Marca en 2024. Sin embargo, ahora ha surgido como una inclusión sorpresa en el equipo de la Copa del Mundo de Bélgica, con Rudi García prefiriéndolo frente a Loïs Openda, que tuvo muy poco tiempo de juego. Fernández-Pardo creció en Bélgica, de padre español y madre italiana, lo que significa que Italia también era una opción para su futuro internacional. A los 15 años dejó Lille para ir a Gent. “Jugó como Eden Hazard, pero sin producto final”, afirmó su ex entrenador Hein Vanhaezebrouck. \"Le mostré clips del Real Madrid, donde Vinícius Júnior a menudo pasa de delantero a banda izquierda para volverse jugable. Matías aprendió eso y se volvió imparable de esa manera\". El Lille pagó 10 millones de euros el verano pasado para traerlo de regreso al norte de Francia. Inicialmente jugó como lateral, pero desde marzo se ha utilizado como central. Con cinco goles y tres asistencias, el veloz delantero ha desplazado a Olivier Giroud del once inicial.","en":"“My heart lies with Spain. Am I sure about who I want to play for? Yes, Spain. Absolutely sure.” Those were the words of Fernandez-Pardo in Marca in 2024. Yet he has now emerged as a surprise inclusion in Belgium’s World Cup squad, with Rudi Garcia favouring him to Loïs Openda, who had too little playing time. Fernandez-Pardo grew up in Belgium, with a Spanish father and an Italian mother – meaning Italy was also an option for his international future. At 15, he left Lille for Gent. “He played like Eden Hazard, but without end product”, said his former coach Hein Vanhaezebrouck. “I showed him clips of Real Madrid, where Vinícius Júnior often drifts from striker to the left wing to become playable. Matias picked that up and became unstoppable that way.” Lille paid €10m last summer to bring him back to northern France. He initially featured on the wing but since March has been used centrally. With five goals and three assists, the lightning-fast striker has pushed Olivier Giroud out of the starting XI."} },
];

export const lineup = {
  formation: '4-3-3',
  startingXI: [1, 15, 4, 3, 21, 7, 24, 8, 10, 9, 11]
};
